#!/usr/bin/env python

import subprocess

def activate_microphones(device_list):
    for device in device_list:
        subprocess.run(["amixer", "-c", "rec", "toggle", device])

if __name__ == "__main__":
    device_list = ["device1", "device2", "device3"]
    activate_microphones(device_list)
